+
+// Helper function for threaded computation
+void matmul_row_block(int n, const float* A, const float* B, float* C, int start_i, int end_i) {
+    for (int i = start_i; i < end_i; ++i) {
+        for (int k = 0; k < n; ++k) {
+            float a_ik = A[i * n + k];
+            for (int j = 0; j < n; ++j) {
+                C[i * n + j] += a_ik * B[k * n + j];
+            }
+        }
+    }
+}
